import json

# 获取输入
try:
    idx = int(inputs.get('In01', 0))
except (ValueError, TypeError):
    idx = 0

json_data = inputs.get('In02', {})

# 解析 JSON（支持字符串或已解析对象）
if isinstance(json_data, str):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        data = {}
else:
    data = json_data if isinstance(json_data, (dict, list)) else {}

# 统一转为有序列表以获取数量 N
if isinstance(data, dict):
    # 键可能为数字字符串，按数字顺序排序
    keys = sorted(data.keys(), key=lambda x: int(x) if str(x).isdigit() else x)
    items = [data[k] for k in keys]
elif isinstance(data, list):
    items = data
else:
    items = []

n = len(items)
if n > 0:
    remainder = idx % n
    prompt = items[remainder]
else:
    prompt = ""

# 输出
outputs[0] = prompt
outputs[1] = None
outputs[2] = None

